// Daily production smoke test. Hits the public API exactly as the web app
// does and checks the model still returns sane appraisals. A deploy that
// breaks the model is invisible until a customer complains -- this catches
// it first. Emits ONE alert item only when something is wrong; returns
// nothing when everything is healthy (no noise).
const API = 'https://tasador-sd.vercel.app';
const problemas = [];

// 1) /health responds and reports itself healthy.
let health = null;
try {
  health = await this.helpers.httpRequest({
    method: 'GET',
    url: API + '/health',
    json: true,
    timeout: 15000,
  });
  if (!health || health.status !== 'ok') {
    problemas.push('El endpoint /health no devolvio status "ok": ' + JSON.stringify(health));
  }
} catch (error) {
  problemas.push('El endpoint /health no respondio: ' + error.message);
}

// 2) The model is loaded and exposes its sectors. We take the first real
//    sector for the appraisal probe, so the test never fails just because
//    a sector name was mistyped.
let sector = null;
let paramsVersion = null;
try {
  const params = await this.helpers.httpRequest({
    method: 'GET',
    url: API + '/v1/model/params',
    json: true,
    timeout: 15000,
  });
  paramsVersion = params && params.version;
  const sectores = params && params.params && params.params.sectors;
  if (!Array.isArray(sectores) || sectores.length === 0) {
    problemas.push('El endpoint /v1/model/params no devolvio la lista de sectores.');
  } else {
    sector = sectores[0];
  }
} catch (error) {
  problemas.push('El endpoint /v1/model/params no respondio: ' + error.message);
}

// 3) A sample appraisal returns a believable number. Values are inside the
//    API's sane ranges (bathrooms must be >= 1).
if (sector) {
  const muestra = {
    sector: sector,
    area_m2: 100,
    bedrooms: 2,
    bathrooms: 2,
    parking_spots: 1,
    furnished: 0,
    age_years: 5,
  };
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: API + '/v1/appraisals',
      body: muestra,
      json: true,
      timeout: 15000,
    });
    if (typeof r.estimate !== 'number' || r.estimate <= 0) {
      problemas.push('La tasacion devolvio un estimate invalido: ' + JSON.stringify(r));
    } else if (r.currency !== 'DOP' || r.period !== 'monthly') {
      problemas.push('La tasacion devolvio moneda/periodo inesperado: ' + r.currency + '/' + r.period);
    } else if (!(r.range_low <= r.estimate && r.estimate <= r.range_high)) {
      problemas.push('Rango incoherente: ' + r.range_low + ' <= ' + r.estimate + ' <= ' + r.range_high);
    }
  } catch (error) {
    problemas.push('La tasacion de ejemplo fallo para el sector "' + sector + '": ' + error.message);
  }
}

// 4) Version coherence between /health and /v1/model/params. A half-finished
//    deploy can leave two different model versions live.
if (health && health.model_version && paramsVersion && health.model_version !== paramsVersion) {
  problemas.push('Version del modelo inconsistente: health=' + health.model_version + ' vs params=' + paramsVersion);
}

// Green run: emit nothing so the alert node never fires.
if (problemas.length === 0) {
  return [];
}

return [{
  json: {
    alerta: 'El smoke test de produccion encontro problemas',
    fecha: $now.toISO(),
    total: problemas.length,
    problemas: problemas,
  },
}];

